import time, random

def linear_search(a, target):
    for i, v in enumerate(a):
        if v == target:
            return i
    return -1

def binary_search(a, target):
    lo, hi, steps = 0, len(a) - 1, 0
    while lo <= hi:
        mid = (lo + hi) // 2
        steps += 1
        if a[mid] == target:
            return mid, steps
        if a[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1, steps

for n in (1_000, 100_000, 1_000_000):
    data = list(range(n))
    target = n - 1
    t0 = time.perf_counter(); linear_search(data, target); t1 = time.perf_counter()
    _, steps = binary_search(data, target)
    print(f"n={n:>9}   linear {(t1-t0)*1000:8.2f} ms   binary {steps:>2} steps")

from collections import deque

graph = {
    "A": ["B", "C"],
    "B": ["D", "E"],
    "C": ["F"],
    "D": [], "E": ["F"], "F": [],
}

def bfs(start):
    seen, order, q = {start}, [], deque([(start, 0)])
    while q:
        node, depth = q.popleft()
        order.append((node, depth))
        for nxt in graph[node]:
            if nxt not in seen:
                seen.add(nxt)
                q.append((nxt, depth + 1))
    return order

print("BFS from A:")
for node, depth in bfs("A"):
    print("  " * depth + f"{node}  (level {depth})")

