std::vector<int> merge_sort(std::vector<int> a) {
    if (a.size() <= 1) return a;
    auto mid = a.begin() + a.size() / 2;
    auto L = merge_sort({a.begin(), mid});
    auto R = merge_sort({mid, a.end()});
    std::vector<int> out;
    out.reserve(a.size());
    std::merge(L.begin(), L.end(), R.begin(), R.end(), std::back_inserter(out));
    return out;
}

int main() {
    std::vector<int> data;
    for (int i = 0; i < 200000; i++) data.push_back((i * 7919) % 100003);

    auto t0 = std::chrono::steady_clock::now();
    auto sorted = merge_sort(data);
    auto t1 = std::chrono::steady_clock::now();

    std::cout << "sorted " << sorted.size() << " items in "
              << std::chrono::duration_cast<std::chrono::milliseconds>(t1 - t0).count()
              << " ms\n";
    std::cout << "is_sorted: " << std::boolalpha
              << std::is_sorted(sorted.begin(), sorted.end()) << "\n";
    std::cout << "first 8:";
    for (int i = 0; i < 8; i++) std::cout << ' ' << sorted[i];
    std::cout << "\n";
}

interface Shape {
    double area();
}

record Circle(double r) implements Shape {
    public double area() { return Math.PI * r * r; }
}

record Rect(double w, double h) implements Shape {
    public double area() { return w * h; }
}

public class Main {
    public static void main(String[] args) {
        Shape[] shapes = { new Circle(2), new Rect(3, 4), new Circle(0.5) };
        double total = 0;
        for (Shape s : shapes) {
            System.out.printf("%-22s area = %8.4f%n", s, s.area());
            total += s.area();
        }
        System.out.printf("%ntotal area = %.4f%n", total);
    }
}

