package main

import (
	"fmt"
	"sync"
)

func main() {
	jobs := make(chan int, 10)
	results := make(chan string, 10)
	var wg sync.WaitGroup

	for w := 1; w <= 3; w++ {
		wg.Add(1)
		go func(id int) {
			defer wg.Done()
			for n := range jobs {
				results <- fmt.Sprintf("worker %d squared %d = %d", id, n, n*n)
			}
		}(w)
	}

	for n := 1; n <= 6; n++ {
		jobs <- n
	}
	close(jobs)
	wg.Wait()
	close(results)

	count := 0
	for range results {
		count++
	}
	fmt.Printf("%d jobs completed by 3 workers\n", count)
}

